<?php

declare(strict_types=1);

namespace HopTop\Pact\Core;

/**
 * The package-level constants of Go package core: Core::VERSION is Go's
 * core.Version, Core::DIGEST_LEN core.DigestLen, Core::KEY_MAX_* the
 * core.KeyMax* limit keys.
 *
 * Namespace HopTop\Pact\Core holds the wire types of PACT: one final readonly
 * class per object definition of the schema and one backed enum per string
 * enum, generated by scripts/gen-types.php (Wire lists them), plus the
 * hand-written JsonObject value model, Digest, Limits and LimitError. Decode
 * untrusted input with HopTop\Pact\Core\StrictJson\StrictJson::decode(). The
 * classes do not enforce the schema's patterns, lengths, enum sets or numeric
 * ranges; a schema validator does.
 */
final class Core
{
    /** The only pact_version value of this draft. */
    public const string VERSION = '0.1';

    /** The length of a base64url SHA-256 value without padding. */
    public const int DIGEST_LEN = 43;

    // The keys of the baseline limits that section 20.1 of the draft names in
    // GatewayMetadata.limits. A LimitError carries one of them.
    public const string KEY_MAX_PRESENTATION_BYTES = 'max_presentation_bytes';
    public const string KEY_MAX_ARTIFACT_PAYLOAD_BYTES = 'max_artifact_payload_bytes';
    public const string KEY_MAX_PROFILE_BYTES = 'max_profile_bytes';
    public const string KEY_MAX_EVIDENCE_ARTIFACTS = 'max_evidence_artifacts';
    public const string KEY_MAX_FIELD_RULES = 'max_field_rules';
    public const string KEY_MAX_JSON_DEPTH = 'max_json_depth';
    public const string KEY_MAX_RESOURCES = 'max_resources';
    public const string KEY_MAX_DESCRIPTION_BYTES = 'max_description_bytes';

    private function __construct() {}
}
